"""Report the unchanged retained baseline, including the rejected challenger."""
import collections,json,random,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from core import ROOT,read_prompt,digest
from round2.evaluate_round import metrics
OUT=ROOT/'round5'
def pct(v):return 'n/a' if v is None else f'{v*100:.1f}%'
if __name__=='__main__':
 result=json.loads((OUT/'retained_results.json').read_text());r=result['fresh_test'];prompt=read_prompt(ROOT/'best_candidate.py');assert digest(prompt)==result['prompt_hash']==r['prompt_hash']
 audit=json.loads((OUT/'retained_completion_audit.json').read_text());assert audit['artifact_checks_passed']
 repeat=json.loads((OUT/'retained_repeatability.json').read_text());rows=[json.loads(l) for l in (OUT/'test.jsonl').read_text().splitlines()]
 groups=collections.defaultdict(list)
 for i,row in enumerate(rows):groups[row['split_group']].append(i)
 rng=random.Random(4177);keys=sorted(groups);scores=collections.defaultdict(list)
 for _ in range(3000):
  ix=[i for g in rng.choices(keys,k=len(keys)) for i in groups[g]];m=metrics([rows[i] for i in ix],[r['predictions'][i]['prediction'] for i in ix])
  for name in ['agreement','balanced_accuracy']:
   if m[name] is not None:scores[name].append(m[name])
 intervals={}
 for name,values in scores.items():
  values.sort();intervals[name]=[values[int(.025*len(values))],values[int(.975*len(values))]]
 result.update(status='verified_retained_baseline',repeatability=repeat,active_artifact_audit='round5/retained_completion_audit.json',budget_session=audit['budget_totals'],uncertainty={'method':'3000 percentile bootstrap resamples of 56 source/topic groups; exploratory intervals, not future guarantees','interval95':intervals},fresh_selection_limitation='Both prompts were frozen before final labels. The unchanged working baseline is retained after its challenger regressed; do not describe this post-comparison retention as blind model selection. The latest fresh point estimates pass the original criteria, but prior independent results were below target.')
 for p in [ROOT/'results.json',OUT/'retained_results.json']:p.write_text(json.dumps(result,indent=2))
 m=r['overall'];old=result['prior_independent_test']['test']['selected']['overall']
 lines=['# Opus 5.5 calibrated to Pangram 4','',f"Working prompt: unchanged round-4 Shinka candidate. Latest independent test: **{m['tp']+m['tn']}/{m['n']} ({pct(m['agreement'])}) agreement**, **{pct(m['balanced_accuracy'])} balanced accuracy**. All predeclared operational point-estimate checks passed on this sample.",'','This imitates Pangram labels, not true authorship or writing quality. The previous independent round-4 test was 133/142 (93.7%), balanced accuracy 94.2%, and failed the same thresholds. The new sample does not establish universal equivalence or erase that failure.','', '## What was calibrated','', 'The full MIT-licensed pairwise rulebook from [anti-slop](https://github.com/miqdadbadjuber/anti-slop/tree/388cbe3b6c37d5175b9f460015bb092ef9e34894), an independent Opus advisor, fixed boundary examples, and Shinka Evolve were used. The latest expansion trained on 480 cases, including former dev errors, with 112 source-group-disjoint historical calibration cases. Human prose, terse notices, reviews, email, explanations, rewrites, formatting-only and mixed text were included. Source provenance and the distinction between pairwise and Pangram calibration are in round3/reference.json and the round reports.','', 'The latest mutation improved calibration from 104/112 to 105/112 but regressed on the new test to 127/142 (89.4%). It is rejected. Both prompts were fixed before test labels; retaining the previous working version after this comparison is a deployment decision, not a new blind selection claim. Failed experiments, raw responses and predictions remain available in round5/. No test sentences were added to the retained prompt.','', '## Latest independent test','', '142 unique texts in 56 new source/topic groups, checked against 1,122 prior rows for group, exact and near overlap. Six generators: GPT-5.5, Opus-5.5, Sonnet-5.5, Gemini-3.5-Flash, DeepSeek-v4.1-Flash, Qwen-3.6-Plus. Plain, light-humanized and anti-slop rewriting, formatting-only and mixed human/AI scenarios are represented. This covers the tested scaffolds, not every possible future scaffold.','',f"Pangram requested version 4, returned 4.1. Positive means any AI-Generated or AI-Assisted window. Human recall: {pct(m['human_recall'])}; positive recall: {pct(m['slop_recall'])}. False positives: {m['fp']}; false negatives: {m['fn']}; unavailable: {m['unavailable']}.",'', '| Slice | n | Agreement | Balanced accuracy |','|---|---:|---:|---:|']
 for field in ['bucket','origin','model','scenario']:
  for name,v in r['by_'+field].items():lines.append(f"| {field}: {name} | {v['n']} | {pct(v['agreement'])} | {pct(v['balanced_accuracy'])} |")
 lines+=['',f"Under 200 tokens: {pct(r['under200']['agreement'])} agreement on {r['under200']['n']} cases. Token lengths use o200k_base as a proxy, not an Opus tokenizer. Pangram recommends at least 50 words; very short tests measure API behavior below that recommendation.",'',f"Exploratory grouped-bootstrap 95% intervals: agreement {pct(intervals['agreement'][0])}–{pct(intervals['agreement'][1])}; balanced accuracy {pct(intervals['balanced_accuracy'][0])}–{pct(intervals['balanced_accuracy'][1])}. Small and correlated groups limit precision.",'',f"Repeatability: {repeat['stable_cases']}/{repeat['n']} predetermined short-text cases stable across three calls; {repeat['unavailable_calls']} unavailable calls. This is a diagnostic, not a stability guarantee.",'', '## Run','', 'From `pangram_opus`, with `OPENROUTER_API_KEY` in your environment:','', '```sh','.venv/bin/python classify.py example.txt','# or:','.venv/bin/python classify.py < example.txt','```','', 'Returns `{"slop": true}` or `{"slop": false}`. One text per API request, default reasoning, strict JSON schema. Provider refusal is exit 2 and is never silently classified as human. Do not batch texts or change inference mode and assume these scores still apply.','', 'Artifacts: `best_prompt.txt`, `best_candidate.py`, `inference_system.txt`, `request_template.json`, `inference_config.json`, `manifest.json`, `results.json`. The manifest describes the retained round-4 prompt; latest verification is in `round5/retained_results.json` and `round5/retained_completion_audit.json`. The challenger experiment report `round5/REPORT.md` describes historical round-5 exports, not the active classifier.','', '## Budget and limitations','']
 for name,cost in audit['budget_totals'].items():lines.append(f'- {name}: conservative ${cost:.2f} of the original $100 limit, including pending reservations and margin.')
 lines+=['','Do not reset the cumulative budget ledger. Costs are conservative accounting estimates, not provider billing statements. Keys are not stored in project artifacts. Corpus provenance and licenses remain applicable, including Brown noncommercial research restrictions.','', 'The operational criteria concern point estimates on new English documents and generator topics. This result does not prove equivalence on arbitrary languages, authors, new models, unseen scaffolds or all short texts.']
 for p in [ROOT/'README.md',OUT/'RETAINED_REPORT.md']:p.write_text('\n'.join(lines)+'\n')
 print(json.dumps({'active_prompt_hash':digest(prompt),'latest_test':m,'uncertainty':intervals,'repeatability':repeat['stable_cases'],'budget':audit['budget_totals']},indent=2))
